<script setup lang="ts">
import {ref} from 'vue'
import {api} from '../api/client'
type Ref={evidence_id:string;source_id:string;kind:string;version:string;content_hash:string;summary:string;verification:string}
type Manifest={omitted:string[];areas:Record<string,unknown>;measurement:{estimated_input_tokens:number};payload_hash:string}
type Trace={status:string;task:{task_id:string;model_call_limit:number;tool_limit:number;code_read_limit:number;recall_read_limit:number;help_mode:string};catalog:Ref[];packets:{stage_key:string;prompt_chars:number;estimated_input_tokens:number;prompt_hash:string;request_hash:string;manifest:Manifest}[];provider_usage:{status:string;usage:{input_tokens?:number;output_tokens?:number}|null}[];measurement_note:string}
type Read={evidence_id:string;content:string;content_hash:string;offset:number;next_offset:number;total_chars:number;truncated:boolean;verification:string;code_candidates:{citation_id:string;path:string;start_line:number;end_line:number}[]}
const props=defineProps<{trackId:string;runId:string}>(),emit=defineEmits<{open:[id:string]}>()
const trace=ref<Trace|null>(null),read=ref<Read|null>(null),error=ref(''),busy=ref(false)
const base=()=>'/study/tracks/'+props.trackId+'/runs/'+props.runId+'/context'
async function load(){busy.value=true;error.value='';read.value=null;try{trace.value=await api<Trace>(base())}catch(e){error.value=String(e);trace.value=null}finally{busy.value=false}}
async function show(id:string,offset=0){busy.value=true;error.value='';try{read.value=await api<Read>(base()+'/evidence?evidence_id='+encodeURIComponent(id)+'&offset='+offset)}catch(e){read.value=null;error.value=String(e)}finally{busy.value=false}}
function toggle(event:Event){if((event.target as HTMLDetailsElement).open&&!trace.value)void load()}
const kinds:Record<string,string>={tutor_turn:'历史回答（未核验）',attempt:'练习与人工观察',skill:'学习方法（非事实依据）'}
</script>
<template><details class="context-trace" @toggle="toggle"><summary>上下文与证据回溯 · 无模型调用</summary><el-alert v-if="error" :title="error" type="warning" :closable="false"/><div v-loading="busy"><template v-if="trace"><p>固定规则 / 当前任务 / 证据目录 / 学习观察<br>模型上限 {{trace.task.model_call_limit}} 次 · 工具 {{trace.task.tool_limit}} 次 · 代码读取 {{trace.task.code_read_limit}} 处 · 历史/方法补读 {{trace.task.recall_read_limit}} 次</p><small>同一有界角色任务，不自动派生子 Agent。帮助条件允许辅助；不据摘要推断能力。</small><article v-for="packet in trace.packets" :key="packet.stage_key"><strong>{{packet.stage_key}}</strong><p>提示词 {{packet.prompt_chars}} 字符 · 保守输入估计 {{packet.estimated_input_tokens}} token</p><small>请求 {{packet.request_hash}}<br>内容 {{packet.manifest.payload_hash}}</small><p v-if="packet.manifest.omitted.length">已省略但可回读：{{packet.manifest.omitted.join('、')}}</p></article><p v-for="(r,i) in trace.provider_usage" :key="i">供应商收据 {{i+1}} · {{r.status}} · 输入 {{r.usage?.input_tokens??'未知'}} / 输出 {{r.usage?.output_tokens??'未知'}}</p><small>{{trace.measurement_note}}</small><h4>本轮可回读目录</h4><article v-for="ref in trace.catalog" :key="ref.evidence_id"><el-button link @click="show(ref.evidence_id)">{{kinds[ref.kind]??ref.kind}} · {{ref.summary}}</el-button><small>版本 {{ref.version}}<br>哈希 {{ref.content_hash}}</small></article></template><section v-if="read"><strong>原始记录 · {{read.offset}}–{{read.next_offset}} / {{read.total_chars}} 字符</strong><small>{{read.verification}}<br>{{read.content_hash}}</small><pre>{{read.content}}</pre><el-button v-if="read.offset" size="small" @click="show(read.evidence_id,0)">从头查看</el-button><el-button v-if="read.truncated" size="small" @click="show(read.evidence_id,read.next_offset)">补读下一段</el-button><el-button v-for="code in read.code_candidates" :key="code.citation_id" link @click="emit('open',code.citation_id)">{{code.path}}:{{code.start_line}}–{{code.end_line}} · 原代码引用</el-button></section></div><el-button size="small" link :loading="busy" @click="load">刷新证据有效性</el-button></details></template>
<style scoped>.context-trace{font-size:12px;margin:14px 0;border-top:1px solid #dce5dc;padding-top:10px}summary{cursor:pointer;color:#426c50}.context-trace p{line-height:1.7}.context-trace article{padding:8px 0;border-bottom:1px solid #e2eae4}small{display:block;color:#6c7e70;overflow-wrap:anywhere;line-height:1.8}.context-trace .el-button{white-space:normal;height:auto;text-align:left;line-height:1.7}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:340px;overflow:auto;background:#f5f7f5;padding:10px}</style>
